                            ) : null}
                            <Box
                                hidden={hasSelectedDiff}
                                sx={{ display: hasSelectedDiff ? 'none' : 'flex', flex: 1, flexDirection: 'column', minHeight: 0 }}
                            >
                                <CardBodyEditor
